type Result = { ok: true; value: { orderId: string; amountKobo: number } } | { ok: false; problems: string[] };

function parseRefund(body: unknown): Result {
  if (typeof body !== "object" || body === null || Array.isArray(body)) return { ok: false, problems: ["body must be an object"] };
  const input = body as Record<string, unknown>;
  const problems: string[] = [];
  for (const key of Object.keys(input)) {
    if (key !== "orderId" && key !== "amountKobo") problems.push(`unknown field ${key}`);
  }
  const { orderId, amountKobo } = input;
  if (typeof orderId !== "string" || !/^ORD-\d{4,10}$/.test(orderId)) problems.push("orderId must look like ORD-1042");
  if (typeof amountKobo !== "number" || !Number.isInteger(amountKobo) || amountKobo <= 0) problems.push("amountKobo must be a positive whole number");
  if (problems.length > 0) return { ok: false, problems };
  return { ok: true, value: { orderId: orderId as string, amountKobo: amountKobo as number } };
}

for (const text of [
  '{"orderId":"ORD-1042","amountKobo":4500000}',
  '{"orderId":"ORD-1042","amountKobo":"4500000"}',
  '{"orderId":"1042","amountKobo":-1,"role":"manager"}',
  "[]",
]) {
  console.log(JSON.stringify(parseRefund(JSON.parse(text))));
}

