function buildUpdate(body: Record<string, unknown>): Record<string, string> | null {
  const update: Record<string, string> = {};
  for (const [key, value] of Object.entries(body)) {
    if (key === "displayName" && typeof value === "string" && value.trim().length >= 1 && value.trim().length <= 60) {
      update.displayName = value.trim();
    } else if (key === "phone" && typeof value === "string" && /^[+\d ]{7,20}$/.test(value)) {
      update.phone = value;
    } else {
      return null;
    }
  }
  return update;
}

