function loadConfig(env: Record<string, string | undefined>) {
  const bad: string[] = [];
  const url = env.GATEWAY_URL;
  const key = env.GATEWAY_KEY;
  if (url === undefined || !url.startsWith("https://")) bad.push("GATEWAY_URL");
  if (key === undefined || key.length < 32) bad.push("GATEWAY_KEY");
  if (bad.length > 0) throw new Error(`invalid configuration: ${bad.join(", ")}`);
  return { url: url as string, key: key as string };
}

try {
  loadConfig({ GATEWAY_URL: "http://payments.example", GATEWAY_KEY: "sk_live_short" });
} catch (error) {
  const message = (error as Error).message;
  console.log(message);
  console.log("contains the key:", message.includes("sk_live_short"));
}
console.log(loadConfig({ GATEWAY_URL: "https://payments.example", GATEWAY_KEY: "k".repeat(32) }).url);
